/** Explicit Bonus owner-exception adapter; actual installer and all native guards remain unchanged. */
import {readFileSync} from 'node:fs';import {resolve} from 'node:path';import {fileURLToPath} from 'node:url';
import {operatorRelease} from './operator-release.mjs';import {verifyBonusRepairCi} from './verify-bonus-repair.mjs';import {createBonusInstallGrant} from './bonus-install-grant.mjs';
export function bindBonusEvidenceProtocol(verify,makeGrant){let verified,started=false;const requireIdentity=evidence=>{if(!verified||evidence!==verified.evidence)throw Error('Bonus verified evidence identity changed');return verified;};return {kind:'runtime-owner-exception/v1',verify:async options=>{if(started)throw Error('Bonus verification already bound');started=true;verified=await verify(options);return verified.evidence;},revalidate:async evidence=>requireIdentity(evidence).revalidate(),createGrant:({evidence,baselineBuildId,environmentSha256})=>{const context=requireIdentity(evidence);return makeGrant({acceptance:evidence.acceptance,evidence,snapshot:context.snapshot,baselineBuildId,environmentSha256});}};}
export async function operatorBonusRepair({candidatePath,plan,execute=false}){const protocol=bindBonusEvidenceProtocol(options=>verifyBonusRepairCi({...options,plan}),createBonusInstallGrant);return operatorRelease({candidatePath,execute,evidenceProtocol:protocol});}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){const [mode,candidatePath,planFile]=process.argv.slice(2);if(process.argv.length!==5||!['verify','deploy'].includes(mode))throw Error('Usage: operator-bonus-repair.mjs <verify|deploy> <clean-candidate> <private-plan.json>');operatorBonusRepair({candidatePath,plan:JSON.parse(readFileSync(planFile)),execute:mode==='deploy'}).then(r=>console.log(JSON.stringify({kind:r.kind,result:r.result,sha:r.sha,runId:r.runId,evidenceDirectory:r.evidenceDirectory,arrivalVerified:r.arrivalVerified??false,ownedResourceCleanupVerified:r.ownedResourceCleanupVerified??false,releaseHandbackVerified:r.releaseHandbackVerified??false,fullGatePassCreated:false}))).catch(e=>{console.error(e);process.exitCode=1;});}
